import io
import unittest

def normalize(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    return " ".join(text.casefold().split())

class NormalizeTests(unittest.TestCase):
    def test_case_and_spaces(self):
        self.assertEqual(normalize("  TOOL   Room "), "tool room")
    def test_empty(self):
        self.assertEqual(normalize("   "), "")
    def test_invalid_type(self):
        with self.assertRaises(ValueError):
            normalize(None)
    def test_original_unchanged(self):
        raw = " Tool "
        normalize(raw)
        self.assertEqual(raw, " Tool ")

log = io.StringIO()
suite = unittest.defaultTestLoader.loadTestsFromTestCase(NormalizeTests)
result = unittest.TextTestRunner(stream=log).run(suite)
print(f"tests={result.testsRun} failures={len(result.failures)} errors={len(result.errors)}")
if not result.wasSuccessful():
    print(log.getvalue())

import math

def cosine(a, b):
    if len(a) != len(b) or not a:
        raise ValueError("Vectors must have the same nonzero dimension")
    for value in list(a) + list(b):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("Values must be numbers")
        if not math.isfinite(value):
            raise ValueError("Values must be finite")
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(y * y for y in b))
    if norm_a == 0 or norm_b == 0:
        return 0.0
    return dot / (norm_a * norm_b)

