def validate(records):
    accepted, rejected, seen = [], [], set()
    for row, record in enumerate(records, start=1):
        reason = None
        if not isinstance(record, dict):
            reason = "not an object"
        elif any(not isinstance(record.get(k), str) or not record[k].strip()
                 for k in ("id", "text")):
            reason = "id and text must be nonempty strings"
        elif record["id"] in seen:
            reason = "duplicate id"
        if reason:
            rejected.append((row, reason))
            continue
        seen.add(record["id"])
        accepted.append({"id": record["id"], "text": record["text"].strip()})
    return accepted, rejected

