from statistics import mean
rows = [(x, 2 * x + [0, 3, -2, 1][x % 4]) for x in range(24)]

def predict(train, x, k):
    closest = sorted(train, key=lambda row: abs(row[0] - x))[:k]
    return mean(y for _, y in closest)

for k in (1, 3, 7):
    fold_errors = []
    for fold in range(3):
        train = [row for i, row in enumerate(rows) if i % 3 != fold]
        valid = [row for i, row in enumerate(rows) if i % 3 == fold]
        fold_errors.append(mean(abs(y - predict(train, x, k)) for x, y in valid))
    print(k, [round(e, 3) for e in fold_errors], round(mean(fold_errors), 3))

