def chunk_words(text, size=8, overlap=2):
    if size <= 0 or not 0 <= overlap < size:
        raise ValueError("Require size > 0 and 0 <= overlap < size")
    words = text.split()
    chunks = []
    for start in range(0, len(words), size - overlap):
        end = min(start + size, len(words))
        chunks.append({"id": f"manual-v1-{start}", "start": start,
                       "end": end, "text": " ".join(words[start:end])})
        if end == len(words):
            break
    return chunks

