def run(proposals, max_steps=3):
    seen = set()
    for step, proposal in enumerate(proposals, start=1):
        if step > max_steps:
            return "budget_exhausted", max_steps
        if proposal == "finish":
            return "completed", step
        if proposal in seen:
            return "stalled", step
        seen.add(proposal)
    return "insufficient_evidence", min(len(proposals), max_steps)

