import hashlib
import json

def digest(value):
    raw = json.dumps(value, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode()).hexdigest()

def prepare():
    evidence = {"id": "doc-a", "text": "The demo library opens at 09:00."}
    action = {"tool": "simulate_delivery", "to": "reviewer@example.invalid",
              "body": evidence["text"] + " [doc-a]"}
    return {"operation_id": "op-001", "status": "awaiting_approval",
            "remaining_steps": 1, "action": action, "source": evidence["id"]}

def resume(state, approved_digest, ledger):
    action = state["action"]
    if action["tool"] != "simulate_delivery" or not state["source"]:
        raise ValueError("invalid_contract")
    current_digest = digest(action)
    if current_digest != approved_digest:
        raise ValueError("approval_mismatch")
    key = state["operation_id"]
    if key in ledger:
        old_digest, receipt = ledger[key]
        if old_digest != current_digest:
            raise ValueError("operation_conflict")
        return receipt
    if state["remaining_steps"] < 1:
        raise ValueError("budget_exhausted")
    state["remaining_steps"] -= 1
    receipt = "receipt-001"
    ledger[key] = (current_digest, receipt)
    state["status"] = "completed_simulation"
    return receipt

