import json
records, actions = {}, []
def submit(key, payload, lose_reply=False):
    fingerprint = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    if key in records:
        old_fingerprint, receipt = records[key]
        if old_fingerprint != fingerprint:
            raise ValueError("idempotency key reused with different payload")
        return receipt
    receipt = f"receipt-{len(actions) + 1}"
    actions.append(payload.copy())
    records[key] = (fingerprint, receipt)
    if lose_reply:
        raise TimeoutError("reply lost")
    return receipt
